package com.lexorion.payroll.repository;
import com.lexorion.payroll.domain.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface PayRunRepository extends JpaRepository<PayRun,UUID>{@Query("select p from PayRun p where p.workspace.id=:workspaceId and (:status is null or p.status=:status)")Page<PayRun>search(@Param("workspaceId")UUID workspaceId,@Param("status")PayRunStatus status,Pageable pageable);Optional<PayRun>findByWorkspaceIdAndPayRunKey(UUID workspaceId,String key);boolean existsByWorkspaceIdAndPayRunKey(UUID workspaceId,String key);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)@Query("select p from PayRun p where p.workspace.id=:workspaceId and p.payRunKey=:key")Optional<PayRun>findScopedForUpdate(@Param("workspaceId")UUID workspaceId,@Param("key")String key);}
